def transform(g):
    g=[list(r) for r in g]; H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    rest=[c for c in cnt if c!=bg]
    border=max(rest,key=lambda c:cnt[c])
    dot=[c for c in rest if c!=border][0]
    vruns=[]; hruns=[]
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]==border:
                s=r
                while r<H and g[r][c]==border: r+=1
                if r-s>=2: vruns.append((c,s,r-1))
            else: r+=1
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]==border:
                s=c
                while c<W and g[r][c]==border: c+=1
                if c-s>=2: hruns.append((r,s,c-1))
            else: c+=1
    if vruns:
        (c1,s1,e1),(c2,s2,e2)=vruns[0],vruns[1]
        out=[r[:] for r in g]
        def band_of(r): return 0 if s1<=r<=e1 else 1
        for r in sorted(rr for rr in range(H) if dot in g[rr]):
            c=g[r].index(dot)
            bc=c1 if band_of(r)==0 else c2
            for cc in range(min(c,bc)+1,max(c,bc)): out[r][cc]=dot
            out[r][c]=4
            partner=(s2+(r-s1)) if band_of(r)==0 else (s1+(r-s2))
            pbc=c2 if band_of(r)==0 else c1
            for cc in range(W):
                if cc!=pbc: out[partner][cc]=dot
        return out
    t=[[g[r][c] for r in range(H)] for c in range(W)]
    res=transform(t)
    return [[res[c][r] for c in range(W)] for r in range(H)]

